const { spawnSync } = require('child_process');
const BIN = '/workspace/dataset/test4_executable';

// cases: array of {label, argv, env}
function run(argv, env) {
  const r = spawnSync(BIN, argv, {
    encoding: 'buffer',
    env: env ? Object.assign({}, process.env, env) : process.env,
    input: Buffer.alloc(0),
  });
  return {
    code: r.status,
    signal: r.signal,
    out: r.stdout ? r.stdout.toString('hex') : '',
    outText: r.stdout ? r.stdout.toString('utf8') : '',
    err: r.stderr ? r.stderr.toString('utf8') : '',
    errHex: r.stderr ? r.stderr.toString('hex') : '',
  };
}

const cases = JSON.parse(require('fs').readFileSync(process.argv[2], 'utf8'));
const results = [];
for (const c of cases) {
  const r = run(c.argv, c.env);
  results.push({ label: c.label, argv: c.argv, env: c.env || null, ...r });
}
console.log(JSON.stringify(results, null, 1));

